{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{
      --bg:#faf4ef; --card:#fff5ee; --accent:#7a4b2a; --muted:#8c6b58; --accent-2:#c37b4f; --glass: rgba(255,255,255,0.6);
      --radius:12px; --gap:20px; font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue";
    }
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg),#fff);color:#2e2a27}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:transparent}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:46px;height:46px;background:linear-gradient(135deg,var(--accent),var(--accent-2));border-radius:10px;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    nav a{color:var(--muted);text-decoration:none;margin:0 10px;font-weight:600}
    nav a.primary{color:var(--accent);border:1px solid transparent;padding:8px 12px;border-radius:8px}
    .hero{padding:48px 28px;border-radius:18px;margin:12px auto;max-width:1100px;background-image:url('assets/img/pattern.svg'), linear-gradient(180deg, rgba(255,255,255,0.8), rgba(255,255,255,0.9));box-shadow:0 6px 30px rgba(46,42,39,0.06);}
    .hero-grid{display:grid;grid-template-columns:1fr 360px;gap:24px;align-items:center}
    h1{margin:0;color:var(--accent);font-size:28px}
    p.lead{margin:8px 0 0;color:var(--muted)}
    .box{background:var(--card);padding:18px;border-radius:12px}
    .muted{color:var(--muted)}
    main{max-width:1100px;margin:18px auto;padding:0 28px}
    .stack{display:grid;gap:18px}
    .two{display:grid;grid-template-columns:1fr 340px;gap:18px}
    .benefits li{margin-bottom:10px}
    .process{display:flex;gap:12px;flex-wrap:wrap}
    .step{flex:1;min-width:140px;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(255,250,245,0.6),rgba(255,255,255,0.5));border:1px solid rgba(122,75,42,0.06)}
    .cta-row{display:flex;gap:12px;align-items:center}
    button.cta{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;border:0;font-weight:700}
    button.ghost{background:transparent;border:1px solid rgba(46,42,39,0.06);padding:10px 12px;border-radius:10px}
    footer{padding:36px 28px;color:var(--muted);font-size:14px}

    /* Reveal animation */
    .reveal{opacity:0;transform:translateY(16px);transition:opacity 600ms ease, transform 600ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){
      .reveal{transition:none;transform:none;opacity:1}
    }

    /* Modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(16,12,10,0.45);display:none;align-items:center;justify-content:center;padding:24px}
    .modal{background:var(--card);padding:20px;border-radius:14px;max-width:680px;width:100%;box-shadow:0 12px 40px rgba(46,42,39,0.18)}
    .modal-header{display:flex;justify-content:space-between;align-items:center}
    .timer{font-weight:800;font-size:28px;color:var(--accent)}

    /* small screens */
    @media (max-width:880px){.hero-grid{grid-template-columns:1fr;}.two{grid-template-columns:1fr}.logo{width:40px;height:40px}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">W</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html" class="primary">Why we do this</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Memberships</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <section class="hero">
    <div class="hero-grid">
      <div>
        <h1>Foundations for steady daily wellbeing</h1>
        <p class="lead">We focus on outcomes, simple habits, and repeatable frameworks so you make progress that feels practical and anchored to real life.</p>
        <div style="margin-top:16px" class="cta-row">
          <button class="cta" onclick="location.href='book.html'">Join a welcome chat</button>
          <button class="ghost" id="try-now-btn">Try a guided exercise</button>
        </div>
      </div>
      <aside class="box">
        <div style="font-weight:700;color:var(--accent)">Membership model</div>
        <div class="muted" style="margin-top:8px">Ongoing guidance, monthly check-ins, and adaptive routines to build sustainable habits—not one-off fixes.</div>
        <div style="margin-top:12px"><strong>Included:</strong>
          <ul style="margin:8px 0 0 18px;color:var(--muted)">
            <li>Weekly short practices</li>
            <li>Monthly coaching pulse</li>
            <li>Access to templates and habit blueprints</li>
          </ul>
        </div>
      </aside>
    </div>
  </section>

  <main>
    <div class="stack">
      <section class="box reveal" aria-labelledby="story">
        <h2 id="story">A little about our approach</h2>
        <p class="muted">We translate intentions into small, measurable actions. The work is less about spectacle and more about the tiny adjustments that compound: a morning cue, a two-minute pause before decisions, a weekly reflection. Over time these add up into dependable routines that support energy, focus, and rest.</p>
      </section>

      <div class="two">
        <section class="box reveal" aria-labelledby="frameworks">
          <h3 id="frameworks">Frameworks we teach</h3>
          <ul class="benefits muted">
            <li><strong>Anchor Blocks:</strong> Fixed micro-routines that stabilize each day.</li>
            <li><strong>Threshold Wins:</strong> Tiny actions that are easy to start and build confidence.</li>
            <li><strong>Reflection Loops:</strong> Simple prompts to adjust habit cues and rewards.</li>
          </ul>
        </section>

        <aside class="box reveal">
          <h4>Real outcomes we track</h4>
          <p class="muted">Less reactivity, clearer priorities, and a dependable evening routine. We help you choose two measurable outcomes and design habits that support them.</p>
        </aside>
      </div>

      <section class="box reveal">
        <h3>How a typical engagement flows</h3>
        <div class="process">
          <div class="step">
            <strong>1. Map</strong>
            <div class="muted">We clarify current routines and desired outcomes.</div>
          </div>
          <div class="step">
            <strong>2. Pilot</strong>
            <div class="muted">Practice 2–3 micro-habits for two weeks and gather simple data.</div>
          </div>
          <div class="step">
            <strong>3. Scale</strong>
            <div class="muted">Adjust cues and supports to make habits reliable.</div>
          </div>
        </div>
      </section>

      <section class="box reveal">
        <h3>Questions people ask</h3>
        <details>
          <summary>Will this be time-consuming?</summary>
          <p class="muted">No. We prioritize tiny actions that fit into your day and compound over time.</p>
        </details>
        <details>
          <summary>Is this a medical program?</summary>
          <p class="muted">No. This is coaching focused on habits and daily frameworks, not medical advice.</p>
        </details>
      </section>

      <section class="box reveal">
        <h3>Ready to begin?</h3>
        <p class="muted">Start with a complimentary 20-minute welcome conversation to see if this membership model fits your life.</p>
        <div style="margin-top:12px">
          <a href="book.html"><button class="cta">Reserve a welcome chat</button></a>
          <button class="ghost" id="try-now-btn-2">Try a guided exercise</button>
        </div>
      </section>
    </div>
  </main>

  <footer>
    <div style="max-width:1100px;margin:0 auto;display:flex;justify-content:space-between;align-items:center">
      <div class="muted">Serving {{CITY}}, {{STATE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div class="muted">Call us: {{PHONE}}</div>
    </div>
  </footer>

  <!-- Guided exercise modal -->
  <div class="modal-backdrop" id="modal" role="dialog" aria-hidden="true">
    <div class="modal" role="document">
      <div class="modal-header">
        <div>
          <div style="font-weight:800">Try it now</div>
          <div class="muted" style="font-size:13px">Choose a short guided practice</div>
        </div>
        <button id="close-modal" aria-label="Close">✕</button>
      </div>

      <div style="margin-top:12px" id="modal-body">
        <div id="choose" class="reveal">
          <button class="cta" onclick="startPractice('breath')">Breathing practice — 2 minutes</button>
          <button class="ghost" style="margin-left:10px" onclick="startPractice('journal')">Guided journaling — 5 min</button>
          <button class="ghost" style="margin-left:10px" onclick="startPractice('intention')">Set an intention — 1 min</button>
        </div>

        <div id="practice" style="display:none;margin-top:14px">
          <div id="practice-title" style="font-weight:700"></div>
          <div id="practice-main" style="margin-top:12px"></div>
          <div style="margin-top:12px;display:flex;gap:10px;align-items:center">
            <div class="timer" id="timer">0:00</div>
            <div style="margin-left:auto">
              <button class="ghost" id="practice-cancel">Cancel</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <script>
    // Modal logic
    const modal = document.getElementById('modal');
    const tryBtns = document.querySelectorAll('#try-now-btn, #try-now-btn-2');
    tryBtns.forEach(b=>b.addEventListener('click',()=>openModal()));
    document.getElementById('close-modal').addEventListener('click',closeModal);
    document.getElementById('practice-cancel').addEventListener('click',closeModal);

    function openModal(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); }
    function closeModal(){ stopPractice(); modal.style.display='none'; modal.setAttribute('aria-hidden','true'); document.getElementById('choose').style.display='block'; document.getElementById('practice').style.display='none'; }

    // Practice runner
    let intervalId=null; let remaining=0;
    function startPractice(kind){
      document.getElementById('choose').style.display='none';
      document.getElementById('practice').style.display='block';
      const title = document.getElementById('practice-title');
      const main = document.getElementById('practice-main');
      const timer = document.getElementById('timer');
      clearInterval(intervalId);

      if(kind === 'breath'){
        title.textContent = 'Two-minute breathing (box breathing)';
        let phase = 0; // inhale-hold-exhale-hold
        const phases = ['Inhale 4s','Hold 4s','Exhale 4s','Hold 4s'];
        remaining = 120; updateTimer();
        main.textContent = phases[phase];
        intervalId = setInterval(()=>{
          remaining--; updateTimer();
          // change phase every 4s
          if(remaining % 4 === 0){ phase = (phase+1)%4; main.textContent = phases[phase]; }
          if(remaining<=0) stopPractice();
        },1000);
      }
      else if(kind === 'journal'){
        title.textContent = 'Five-minute focused journaling';
        remaining = 300; updateTimer();
        main.innerHTML = '<ol style="padding-left:18px;margin:0"><li>What went well this week?</li><li>One small shift I can try next week?</li><li>One quick note of gratitude.</li></ol>';
        intervalId = setInterval(()=>{ remaining--; updateTimer(); if(remaining<=0) stopPractice(); },1000);
      }
      else if(kind === 'intention'){
        title.textContent = 'Set a short intention';
        remaining = 60; updateTimer();
        main.innerHTML = '<div><label style="font-weight:600">Write a one-line intention</label><br><input id="intent-input" style="width:100%;margin-top:8px;padding:8px;border-radius:8px;border:1px solid #eee" placeholder="My intention for today is..."/></div>';
        intervalId = setInterval(()=>{ remaining--; updateTimer(); if(remaining<=0){ saveIntention(); stopPractice(); } },1000);
      }
    }
    function updateTimer(){ const m = Math.floor(remaining/60); const s = remaining%60; document.getElementById('timer').textContent = m+':'+String(s).padStart(2,'0'); }
    function stopPractice(){ clearInterval(intervalId); intervalId=null; }
    function saveIntention(){ const v = document.getElementById('intent-input')?.value || ''; if(v.trim()){ alert('Saved: "'+v+'" — we recommend keeping it visible today.'); } }

    // Reveal on scroll with reduced-motion support
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const revealEls = Array.from(document.querySelectorAll('.reveal'));
      if(prefersReduced){ revealEls.forEach(e=>e.classList.add('visible')); return; }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(ent=>{ if(ent.isIntersecting){ ent.target.classList.add('visible'); io.unobserve(ent.target); } });
      },{threshold:0.12});
      revealEls.forEach(e=>io.observe(e));
    })();

    // Accessibility: close modal on Escape
    window.addEventListener('keydown', (e)=>{ if(e.key === 'Escape' && modal.style.display === 'flex') closeModal(); });
  </script>
</body>
</html>"} 
