<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff8f3;--card:#fff;--accent:#6b3f28;--muted:#8a6d59;--accent-2:#c07b53}
    body{margin:0;font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto; background:var(--bg);color:#2d2a27}
    header{display:flex;justify-content:space-between;padding:18px 26px;align-items:center}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),var(--accent-2));color:white;display:flex;align-items:center;justify-content:center;font-weight:800}
    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    .wrap{max-width:1100px;margin:0 auto;padding:18px}
    .intro{display:flex;align-items:center;gap:18px}
    h1{margin:0;color:var(--accent)}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
    .card{background:var(--card);padding:16px;border-radius:12px;border:1px solid rgba(45,42,39,0.04)}
    .card h3{margin:0 0 6px 0;color:var(--accent)}
    .muted{color:var(--muted)}
    .price-tag{font-weight:800;color:var(--accent)}
    .cta-row{margin-top:12px}
    button.cta{background:var(--accent);color:white;border:0;padding:8px 12px;border-radius:10px}
    button.secondary{background:transparent;border:1px solid rgba(45,42,39,0.06);padding:8px 12px;border-radius:10px}

    .reveal{opacity:0;transform:translateY(18px);transition:opacity 560ms ease, transform 560ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){ .reveal{transition:none;opacity:1;transform:none} }

    @media(max-width:980px){.grid{grid-template-columns:1fr}.intro{flex-direction:column;align-items:flex-start}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div class="logo">W</div>
      <div style="line-height:1">
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Main</a>
      <a href="about.html">Philosophy</a>
      <a href="services.html" style="font-weight:700;color:var(--accent)">Offerings</a>
      <a href="programs.html">Memberships</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="intro">
      <div>
        <h1>What we guide you through</h1>
        <p class="muted">Practical sessions and lightweight tools aimed at behaviour change. Pick single-session help or ongoing coaching within our membership model.</p>
      </div>
      <div style="margin-left:auto">
        <button class="cta" onclick="location.href='book.html'">Book a session</button>
        <button class="secondary" id="try-now">Try a short exercise</button>
      </div>
    </section>

    <section style="margin-top:20px">
      <div class="grid">
        <article class="card reveal">
          <h3>Habit Design Session</h3>
          <div class="muted">One 60-minute practical meeting to design 1–2 micro-habits, with a repeatable plan.</div>
          <div style="margin-top:10px" class="price-tag">Suggested: pay-what-works</div>
          <div class="cta-row"><button class="cta" onclick="location.href='book.html'">Reserve this session</button></div>
        </article>

        <article class="card reveal">
          <h3>Routine Reset</h3>
          <div class="muted">Two sessions plus a 2-week accountability check to reset mornings or evenings.</div>
          <div style="margin-top:10px" class="price-tag">Includes templates and check-ins</div>
          <div class="cta-row"><button class="cta" onclick="location.href='book.html'">Start the reset</button></div>
        </article>

        <article class="card reveal">
          <h3>Micro-Groups</h3>
          <div class="muted">A four-week small-group run with focused weekly prompts and shared reflections.</div>
          <div style="margin-top:10px" class="price-tag">Limited seats per cohort</div>
          <div class="cta-row"><button class="cta" onclick="location.href='contact.html'">Join a cohort</button></div>
        </article>

        <article class="card reveal">
          <h3>Workplace Rhythm Audit</h3>
          <div class="muted">A compact toolkit for teams: meeting cadences, clarity rituals, and micro-break routines.</div>
          <div style="margin-top:10px" class="price-tag">Custom quote</div>
          <div class="cta-row"><button class="cta" onclick="location.href='contact.html'">Request a proposal</button></div>
        </article>

        <article class="card reveal">
          <h3>Digital Templates</h3>
          <div class="muted">A library of habit templates, checklists, and reflection prompts you can reuse.</div>
          <div style="margin-top:10px" class="price-tag">Included for members</div>
          <div class="cta-row"><button class="cta" onclick="location.href='programs.html'">See memberships</button></div>
        </article>

        <article class="card reveal">
          <h3>Short Consult — 20 min</h3>
          <div class="muted">A quick alignment chat to decide the best next step.</div>
          <div style="margin-top:10px" class="price-tag">Complimentary</div>
          <div class="cta-row"><button class="cta" onclick="location.href='book.html'">Schedule now</button></div>
        </article>
      </div>
    </section>

    <section style="margin-top:24px" class="reveal">
      <h2>How we talk about value</h2>
      <p class="muted">Rather than focusing on fixed price tiers for one-off advice, we emphasize recurring support and the cumulative value of habit practice. Many clients select our membership when they want measurable, ongoing shifts rather than episodic guidance.</p>
    </section>

    <section style="margin-top:18px" class="reveal">
      <h2>Not medical care</h2>
      <p class="muted">Coaching centers on behavior, routines, and practical frameworks—no diagnostic or medical services are provided.</p>
    </section>
  </main>

  <div style="height:60px"></div>

  <!-- Modal copy from site for practice -->
  <div id="practice-modal" style="display:none;position:fixed;inset:0;background:rgba(12,8,6,0.45);align-items:center;justify-content:center">
    <!-- Injected by script when used -->
  </div>

  <script>
    // Minimal reuse of modal logic tailored for services page
    document.getElementById('try-now').addEventListener('click',()=>{
      // Simple breathing overlay
      const overlay = document.createElement('div');
      overlay.style.position='fixed'; overlay.style.inset='0'; overlay.style.background='rgba(12,8,6,0.45)'; overlay.style.display='flex'; overlay.style.alignItems='center'; overlay.style.justifyContent='center'; overlay.id='temp-overlay';
      const box = document.createElement('div'); box.style.background='#fff'; box.style.padding='20px'; box.style.borderRadius='12px'; box.style.maxWidth='520px'; box.style.width='90%';
      box.innerHTML = '<div style="font-weight:800;color:var(--accent)">One-minute breathing</div><div style="margin-top:10px">Follow the words: <span id="cue">Inhale</span></div><div style="margin-top:12px"><button id="close-temp" style="padding:8px 12px;border-radius:8px;border:0;background:var(--accent);color:#fff">Close</button></div>';
      overlay.appendChild(box); document.body.appendChild(overlay);
      let phase=0; const cues=['Inhale','Hold','Exhale','Hold']; const el = box.querySelector('#cue'); const id = setInterval(()=>{ phase=(phase+1)%4; el.textContent=cues[phase]; },1000*2);
      box.querySelector('#close-temp').addEventListener('click',()=>{ clearInterval(id); overlay.remove(); });
    });

    // Reveal logic (same approach)
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const els = Array.from(document.querySelectorAll('.reveal'));
      if(prefersReduced){ els.forEach(e=>e.classList.add('visible')); return; }
      const io = new IntersectionObserver((entries)=>{ entries.forEach(ent=>{ if(ent.isIntersecting){ ent.target.classList.add('visible'); io.unobserve(ent.target); } }); },{threshold:0.12});
      els.forEach(e=>io.observe(e));
    })();
  </script>
</body>
</html>"} 
