    nav a{margin:0 8px;color:var(--muted);text-decoration:none}
    .wrap{max-width:1100px;margin:20px auto;padding:0 24px}
    h1{color:var(--accent)}
    .tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}
