    <div style="display:flex;gap:12px;align-items:center">
      <div style="width:44px;height:44px;background:linear-gradient(135deg,var(--accent),#c37b4f);border-radius:10px;color:#fff;display:flex;align-items:center;justify-content:center;font-weight:800">W</div>
      <div style="line-height:1">
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Overview</a>
      <a href="about.html">Team</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html" style="font-weight:700;color:var(--accent)">Memberships</a>
      <a href="book.html">Book</a>
    </nav>
